/** Whether the owner has a usable email address. */
boolean hasEmail(Owner owner) {
    return owner.getEmail() != null && !owner.getEmail().isBlank();
}

/** The number of owners sharing this owner's household (owners with the same householdId,
 *  counting the owner itself). An owner with no household id is a single-member household. */
int householdSize(Owner owner) {
    String householdId = owner.getHouseholdId();
    if (householdId == null || owner.getLastName() == null) {
        return 1;
    }
    int size = 0;
    for (Owner other : ownerRepository.findByLastName(owner.getLastName())) {
        if (householdId.equals(other.getHouseholdId())) {
            size++;
        }
    }
    return Math.max(size, 1);
}

/**
 * The owner's membership points. Starting from 0: add 2 when an email address is present, add 1
 * when the owner has no namesakes (namesakeCount is 0), add 2 for a household of 3 or more
 * members, and add 3 when the owner's tenure exceeds 365 days.
 */
int membershipPoints(Owner owner) {
    int points = 0;
    if (hasEmail(owner)) {
        points += 2;
    }
    if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
        points += 1;
    }
    if (householdSize(owner) >= 3) {
        points += 2;
    }
    long tenureDays = owner.getRegistrationDate() == null ? 0
            : ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now());
    if (tenureDays > 365) {
        points += 3;
    }
    return points;
}

/**
 * The owner's numeric membership level, mapped from {@link #membershipPoints(Owner)}: level 1 for
 * 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
 */
int membershipLevel(Owner owner) {
    int points = membershipPoints(owner);
    if (points <= 1) {
        return 1;
    }
    if (points <= 3) {
        return 2;
    }
    if (points <= 5) {
        return 3;
    }
    return 4;
}

